// Helper function to create ingredients with custom images
// To add a custom image for an ingredient:
// 1. Place your image file in the PUBLIC folder: public/ingredients/
// 2. Name it using the ingredient name (lowercase, spaces replaced with hyphens)
//    Example: "Bat wings" -> bat-wings.png
// 3. The image will be automatically loaded from: /witchsoup/ingredients/{name}.png
// 4. Supported formats: .png, .jpg, .jpeg, .gif, .webp
const createIngredient = (name, letter, description = '') => {
  const imageName = name.toLowerCase().replace(/\s+/g, '-');
  // Use process.env.PUBLIC_URL for production builds, or relative path for dev
  const basePath = process.env.PUBLIC_URL || '';
  return {
    name,
    icon: `${basePath}/ingredients/${imageName}.png`,
    iconType: 'image',
    letter,
    description
  };
};

