function CountrySelector({ ingredient, countries, onSelectCountry, onBack, selectedIngredients }) {
  const [selectedLetter, setSelectedLetter] = useState(null);

  const allLetters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');

  const filteredCountries = useMemo(() => {
    const toFilter = selectedLetter
      ? countries.filter(country => country.name.charAt(0).toUpperCase() === selectedLetter)
      : countries;
    return toFilter.sort((a, b) => a.name.localeCompare(b.name));
  }, [countries, selectedLetter]);

  const isCountrySelected = (country) => {
    return selectedIngredients.some(ingredient => 
      ingredient.country && ingredient.country.code === country.code
    );
  };

  return (
    <Container>
      <CountriesSection>
        <Header>
          <BackButton onClick={onBack}>
            <FiArrowLeft size={20} />
          </BackButton>
          <HeaderContent>
            <Title>Choose Country</Title>
            <Subtitle>
              <IngredientIcon>
                {ingredient?.iconType === 'image' ? (
                  <img 
                    src={ingredient.icon} 
                    alt={ingredient.name}
                    style={{
                      width: '1.5em',
                      height: '1.5em',
                      objectFit: 'contain'
                    }}
                  />
                ) : (
                  <Icon icon={ingredient?.icon} width="1.5em" height="1.5em" />
                )}
              </IngredientIcon>
              {ingredient?.name} is from...
            </Subtitle>
          </HeaderContent>
        </Header>

        <LetterFilterContainer>
          {allLetters.map(letter => (
            <LetterButton
              key={letter}
              active={selectedLetter === letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
            >
              {letter}
            </LetterButton>
          ))}
        </LetterFilterContainer>

        <CountriesContainer>
          <ScrollableArea>
            <CountriesGrid>
                <AnimatePresence>
                  {filteredCountries.map((country, index) => {
                    const isSelected = isCountrySelected(country);
                    return (
                      <CountryButton
                        key={country.code}
                        className={isSelected ? 'selected' : ''}
                        onClick={() => {
                          if (!isSelected) {
                            onSelectCountry(country);
                          }
                        }}
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.8 }}
                        transition={{ delay: index * 0.02 }}
                        whileHover={!isSelected ? { scale: 1.02 } : {}}
                        whileTap={!isSelected ? { scale: 0.98 } : {}}
                      >
                        <CountryFlag className={`fi fi-${country.code}`} />
                        <CountryName>{country.name}</CountryName>
                      </CountryButton>
                    );
                  })}
                </AnimatePresence>
              </CountriesGrid>
          </ScrollableArea>
        </CountriesContainer>
      </CountriesSection>

      <Sidebar>
        <IngredientInfo
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.3 }}
        >
          <IngredientInfoTitle>
            🥘 Ingredient
          </IngredientInfoTitle>
          
          <IngredientDisplay>
            <IngredientLetter>{ingredient?.letter}</IngredientLetter>
            <IngredientDetails>
              <IngredientName>
                <IngredientEmoji>
                  {ingredient?.iconType === 'image' ? (
                    <img 
                      src={ingredient.icon} 
                      alt={ingredient.name}
                      style={{
                        width: '1em',
                        height: '1em',
                        objectFit: 'contain'
                      }}
                    />
                  ) : (
                    <Icon icon={ingredient?.icon} width="1em" height="1em" />
                  )}
                </IngredientEmoji>
                {ingredient?.name}
              </IngredientName>
              {ingredient?.japanese && (
                <IngredientJapaneseName>{ingredient.japanese}</IngredientJapaneseName>
              )}
              {ingredient?.description && (
                <IngredientDescription>{ingredient.description}</IngredientDescription>
              )}
              <div style={{ color: '#ff6b35', fontSize: '0.85rem' }}>
                Choose a country
              </div>
            </IngredientDetails>
          </IngredientDisplay>
        </IngredientInfo>
      </Sidebar>
    </Container>
  );
}

export default CountrySelector;
