const EmptyState = styled.div`
  text-align: center;
  color: #ff6b35;
  font-style: italic;
  padding: 2rem;
`;

function IngredientSelector({
  ingredients,
  selectedIngredients,
  onAddIngredient,
  onRemoveIngredient,
  onOpenCountryModal,
  canProceed,
  onBuildSoup,
  progress
}) {
  const [selectedLetter, setSelectedLetter] = useState(null);

  const allLetters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');

  const filteredIngredients = useMemo(() => {
    const toFilter = selectedLetter 
      ? ingredients.filter(ing => ing.letter === selectedLetter)
      : ingredients;
    
    // Group by letter
    const grouped = {};
    toFilter.forEach(ingredient => {
      if (!grouped[ingredient.letter]) {
        grouped[ingredient.letter] = [];
      }
      grouped[ingredient.letter].push(ingredient);
    });
    
    return grouped;
  }, [ingredients, selectedLetter]);

  const isSelected = (ingredient) => {
    return selectedIngredients.some(selected => selected.name === ingredient.name);
  };

  const getButtonText = () => {
    if (selectedIngredients.length < 3) {
      const remaining = 3 - selectedIngredients.length;
      return `Select ${remaining} more ingredient${remaining > 1 ? 's' : ''}`;
    }
    
    const withoutCountry = selectedIngredients.filter(ing => !ing.country).length;
    if (withoutCountry > 0) {
      return `Select ${withoutCountry} more countr${withoutCountry > 1 ? 'ies' : 'y'}`;
    }
    
    return `🧙‍♀️ Soup Magic (${selectedIngredients.length} ingredients)`;
  };

  return (
    <Container>
      <IngredientsSection>
        <LetterFilterContainer>
          {allLetters.map(letter => (
            <LetterButton
              key={letter}
              active={selectedLetter === letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
            >
              {letter}
            </LetterButton>
          ))}
        </LetterFilterContainer>

        <IngredientsGrid>
          {Object.keys(filteredIngredients).sort().map(letter => (
            <LetterSection
              key={letter}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3 }}
              style={{ gridColumn: '1 / -1' }}
            >
              <LetterHeader>{letter}</LetterHeader>
              <div style={{ 
                display: 'grid', 
                gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', 
                gap: '1rem' 
              }}>
                {filteredIngredients[letter].map((ingredient, index) => (
                  <IngredientCard
                    key={ingredient.name}
                    selected={isSelected(ingredient)}
                    onClick={() => {
                      if (isSelected(ingredient)) {
                        const selectedIndex = selectedIngredients.findIndex(
                          selected => selected.name === ingredient.name
                        );
                        onRemoveIngredient(selectedIndex);
                      } else {
                        onAddIngredient(ingredient);
                      }
                    }}
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: index * 0.05 }}
                  >
                    <IngredientIcon>
                      <img 
                        src={ingredient.icon} 
                        alt={ingredient.name}
                        onError={(e) => {
                          // Show placeholder if image not found
                          e.target.style.display = 'none';
                          e.target.nextSibling.style.display = 'flex';
                        }}
                        style={{
                          width: '3rem',
                          height: '3rem',
                          objectFit: 'contain'
                        }}
                      />
                      <div style={{
                        display: 'none',
                        width: '3rem',
                        height: '3rem',
                        background: 'linear-gradient(145deg, #8b5cf6 0%, #7c3aed 100%)',
                        borderRadius: '8px',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '1.5rem',
                        color: 'white',
                        fontWeight: 'bold'
                      }}>
                        {ingredient.letter}
                      </div>
                    </IngredientIcon>
                    <IngredientName>{ingredient.name}</IngredientName>
                  </IngredientCard>
                ))}
              </div>
            </LetterSection>
          ))}
        </IngredientsGrid>
      </IngredientsSection>

      <Sidebar>
        <SelectedIngredientsPanel
          initial={{ x: 50, opacity: 0 }}
          animate={{ x: 0, opacity: 1 }}
          transition={{ delay: 0.2 }}
        >
          <SelectedTitle>
            🥢 Your Soup ({selectedIngredients.length}/3)
          </SelectedTitle>
          
          <ProgressBar progress={progress} />
          
          {selectedIngredients.length === 0 ? (
            <EmptyState>
              No ingredients yet.<br />
              Choose 3 ingredients!
            </EmptyState>
          ) : (
            <AnimatePresence>
              {selectedIngredients.map((ingredient, index) => (
                <SelectedItem
                  key={ingredient.id}
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
                  transition={{ duration: 0.2 }}
                >
                  <SelectedLetter>{ingredient.letter}</SelectedLetter>
                  <SelectedInfo>
                    <SelectedName>{ingredient.name}</SelectedName>
                    <SelectedCountry>
                      {ingredient.country ? (
                        <>
                          <CountryFlag className={`fi fi-${ingredient.country.code}`} />
                          {ingredient.country.name}
                        </>
                      ) : (
                        <span style={{ color: '#ef4444' }}>Select Country</span>
                      )}
                    </SelectedCountry>
                  </SelectedInfo>
                  <ActionButton
                    onClick={() => onOpenCountryModal(index)}
                    title={ingredient.country ? 'Change country' : 'Select country'}
                  >
                    🌍
                  </ActionButton>
                  <ActionButton
                    onClick={() => onRemoveIngredient(index)}
                    title="Remove ingredient"
                  >
                    <FiX color="#ef4444" />
                  </ActionButton>
                </SelectedItem>
              ))}
            </AnimatePresence>
          )}
          
          <BuildButton
            disabled={!canProceed}
            onClick={onBuildSoup}
            whileHover={canProceed ? { scale: 1.02 } : {}}
            whileTap={canProceed ? { scale: 0.98 } : {}}
          >
            {getButtonText()}
          </BuildButton>
        </SelectedIngredientsPanel>
      </Sidebar>
    </Container>
  );
}

export default IngredientSelector;
